def main():
    root = pathlib.Path(__file__).resolve().parent.parent
    seen = set()
    rows = []
    for row in ROWS:
        assert len(row) == 4 and all(isinstance(cell, str) and cell for cell in row), row
        if row[0] in seen:
            continue
        seen.add(row[0])
        rows.append(list(row))
    for pattern in PATTERNS:
        assert len(pattern) == 4, pattern
    body = (
        "/*\n * Table de traduction de l'interface — GÉNÉRÉE par scripts/i18n-table.py (ne pas modifier à la main).\n"
        " * [français, English, Español, Filipino] ; modèles : [regex sur le français, en, es, fil].\n */\n"
        f"globalThis.RQI18nTable = {json.dumps(rows, ensure_ascii=False, indent=0)};\n"
        f"globalThis.RQI18nPatterns = {json.dumps([list(p) for p in PATTERNS], ensure_ascii=False, indent=0)};\n"
    )
    for target in ("public/js/i18n-table.js", "chrome-extension/i18n-table.js"):
        (root / target).write_text(body, encoding="utf-8")
    print(f"{len(rows)} textes, {len(PATTERNS)} modèles")


if __name__ == "__main__":
    main()
